<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSamlIdpMetadataUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSamlIdpMetadataUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withSamlIdpMetadataUrl,
 * getSamlIdpMetadataUrl/samlIdpMetadataUrl accessors, and isSamlIdpMetadataUrlChanged with/without original.
 */
class TenantLoginProviderSamlIdpMetadataUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSamlIdpMetadataUrl creates a new instance with the SamlIdpMetadataUrl set
     * from a string value, and getSamlIdpMetadataUrl returns the primitive string.
     */
    public function testWithSamlIdpMetadataUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpMetadataUrlAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpMetadataUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSamlIdpMetadataUrl());
    }
    /**
     * Asserts that withsamlIdpMetadataUrl has access to the value object
     * from a string value, and getSamlIdpMetadataUrl returns the primitive string.
     */
    public function testWithSamlIdpMetadataUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpMetadataUrlAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpMetadataUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->samlIdpMetadataUrl()->value());
    }
    public function testChangedSamlIdpMetadataUrl(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpMetadataUrlAccessorUnitTest();
        $original = $holder->withSamlIdpMetadataUrl('one');
        $same = $holder->withSamlIdpMetadataUrl('one');
        $modified = $holder->withSamlIdpMetadataUrl('other');

        // Act
        $unchanged = $holder->isSamlIdpMetadataUrlChanged();
        $withSame = $original->isSamlIdpMetadataUrlChanged($same);
        $withDiferent = $original->isSamlIdpMetadataUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSamlIdpMetadataUrlAccessorUnitTest
{
    use TenantLoginProviderSamlIdpMetadataUrlAccessor;
}
